"use client";

import dynamic from "next/dynamic";
import { motion } from "motion/react";
import type { AgentState } from "@/components/ui/orb";

const Orb = dynamic(() => import("@/components/ui/orb").then((m) => m.Orb), { ssr: false });

const COLORS: [string, string] = ["#CADCFC", "#A0B9D1"];

export function VoiceOrb({
  size,
  agentState,
  live,
  connecting,
  onToggle,
  getInputVolume,
  getOutputVolume,
}: {
  size: number;
  agentState: AgentState;
  live: boolean;
  connecting: boolean;
  onToggle: () => void;
  getInputVolume: () => number;
  getOutputVolume: () => number;
}) {
  const manual = live && agentState !== "thinking";
  return (
    <motion.button
      type="button"
      aria-label={live ? "End conversation" : "Start talking"}
      onClick={onToggle}
      layout
      transition={{ type: "spring", stiffness: 220, damping: 30 }}
      style={{ width: size, height: size }}
      whileTap={{ scale: 0.96 }}
      className="relative shrink-0 rounded-full outline-none focus-visible:ring-2 focus-visible:ring-[#A0B9D1] focus-visible:ring-offset-4"
    >
      <div
        className="pointer-events-none absolute inset-[6%] rounded-full blur-2xl transition-opacity duration-700"
        style={{ background: "radial-gradient(circle, #CADCFC 0%, transparent 70%)", opacity: live ? 0.9 : 0.45 }}
      />
      <div className="relative h-full w-full">
        <Orb
          colors={COLORS}
          seed={7}
          agentState={live ? agentState : connecting ? "thinking" : null}
          volumeMode={manual ? "manual" : "auto"}
          getInputVolume={getInputVolume}
          getOutputVolume={getOutputVolume}
        />
      </div>
    </motion.button>
  );
}

"use client";

import { motion } from "motion/react";
import { ShoppingBag, Store, Truck } from "lucide-react";
import type { FulfillmentMode } from "@/lib/types";
import { cn } from "@/lib/utils";

const OPTIONS: Array<{ mode: FulfillmentMode; label: string; Icon: typeof Truck }> = [
  { mode: "instacart_delivery", label: "Delivery", Icon: Truck },
  { mode: "store_pickup", label: "Pickup", Icon: ShoppingBag },
  { mode: "in_store", label: "In store", Icon: Store },
];

export function FulfillmentSwitch({
  mode,
  onChange,
}: {
  mode: FulfillmentMode;
  onChange: (mode: FulfillmentMode) => void;
}) {
  return (
    <div role="radiogroup" className="grid grid-cols-3 rounded-full bg-surface p-1">
      {OPTIONS.map(({ mode: m, label, Icon }) => {
        const active = m === mode;
        return (
          <button
            key={m}
            role="radio"
            aria-checked={active}
            onClick={() => onChange(m)}
            className={cn(
              "relative flex h-9 items-center justify-center gap-1.5 rounded-full text-[13px] font-medium transition-colors",
              active ? "text-ink" : "text-subtle hover:text-ink",
            )}
          >
            {active && (
              <motion.span
                layoutId="fulfillment-pill"
                className="absolute inset-0 rounded-full bg-white shadow-[0_1px_2px_rgba(0,0,0,0.06),0_2px_8px_rgba(0,0,0,0.04)]"
                transition={{ type: "spring", stiffness: 420, damping: 34 }}
              />
            )}
            <Icon className="relative size-[15px]" strokeWidth={1.75} />
            <span className="relative">{label}</span>
          </button>
        );
      })}
    </div>
  );
}

import Image from "next/image";
import type { Product } from "@/lib/types";
import { cn } from "@/lib/utils";

export function ProductThumb({ product, size = 56, className }: { product: Product; size?: number; className?: string }) {
  return (
    <div
      className={cn("relative shrink-0 overflow-hidden rounded-2xl bg-surface", className)}
      style={{ width: size, height: size }}
    >
      {product.image_url ? (
        <Image
          src={product.image_url}
          alt={product.name}
          fill
          sizes={`${size * 2}px`}
          className="object-contain p-1.5 mix-blend-multiply"
        />
      ) : (
        <div className="flex h-full w-full items-center justify-center font-display text-xl text-subtle">
          {product.name.charAt(0)}
        </div>
      )}
    </div>
  );
}

"use client";

import { AnimatePresence, motion } from "motion/react";
import { Check, RotateCcw } from "lucide-react";
import { ProductThumb } from "@/components/basket/product-thumb";
import type { OrderItem, OrderState } from "@/lib/types";
import { cn } from "@/lib/utils";

const money = (n: number) => `$${n.toFixed(2)}`;

function Row({ item, onTogglePicked, inStore }: { item: OrderItem; onTogglePicked: (id: string) => void; inStore: boolean }) {
  const { product, qty, status } = item;
  const oos = status === "out_of_stock";
  const picked = status === "picked";
  return (
    <motion.li
      layout
      initial={{ opacity: 0, y: 12, filter: "blur(4px)" }}
      animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
      exit={{ opacity: 0, x: -24, transition: { duration: 0.2 } }}
      transition={{ type: "spring", stiffness: 300, damping: 30 }}
      className="flex items-center gap-3.5 py-3"
    >
      {inStore && (
        <button
          aria-label={picked ? "Mark not picked" : "Mark picked"}
          onClick={() => onTogglePicked(product.id)}
          disabled={oos}
          className={cn(
            "flex size-6 shrink-0 items-center justify-center rounded-full border transition-colors",
            picked ? "border-ink bg-ink text-white" : "border-hairline bg-white",
            oos && "opacity-30",
          )}
        >
          {picked && <Check className="size-3.5" strokeWidth={2.5} />}
        </button>
      )}
      <ProductThumb product={product} className={cn((oos || picked) && "opacity-50")} />
      <div className="min-w-0 flex-1">
        <p className={cn("truncate text-[15px] font-medium leading-tight", (oos || picked) && "text-subtle", oos && "line-through")}>
          {product.name}
        </p>
        <p className="mt-0.5 truncate text-[13px] text-subtle">
          {product.size}
          {inStore ? ` · Aisle ${product.aisle}` : ` · ${product.brand}`}
        </p>
        {status === "swapped" && item.swapped_from && (
          <span className="mt-1.5 inline-flex max-w-full items-center gap-1 rounded-full bg-swap px-2 py-0.5 text-[11.5px] font-medium text-swap-ink">
            <RotateCcw className="size-3 shrink-0" strokeWidth={2} />
            <span className="truncate">
              Swapped from {item.swapped_from.brand}
              {item.note ? ` · ${item.note}` : ""}
            </span>
          </span>
        )}
        {oos && (
          <span className="mt-1.5 inline-flex items-center rounded-full bg-oos px-2 py-0.5 text-[11.5px] font-medium text-oos-ink">
            Out of stock
          </span>
        )}
      </div>
      <div className="text-right">
        <p className={cn("font-mono text-[14px] tabular", oos && "text-subtle line-through")}>{money(product.price * qty)}</p>
        {qty > 1 && <p className="font-mono text-[12px] text-subtle tabular">×{qty}</p>}
      </div>
    </motion.li>
  );
}

export function OrderList({ order, onTogglePicked }: { order: OrderState; onTogglePicked: (id: string) => void }) {
  const inStore = order.fulfillment.mode === "in_store";
  const items = inStore
    ? [...order.items].sort((a, b) => Number(a.product.aisle) - Number(b.product.aisle))
    : order.items;

  const groups = inStore
    ? items.reduce<Array<{ aisle: string; items: OrderItem[] }>>((acc, item) => {
        const last = acc[acc.length - 1];
        if (last && last.aisle === item.product.aisle) last.items.push(item);
        else acc.push({ aisle: item.product.aisle, items: [item] });
        return acc;
      }, [])
    : [{ aisle: "", items }];

  return (
    <div>
      {groups.map((g) => (
        <div key={g.aisle || "all"}>
          {inStore && (
            <p className="pt-4 pb-1 text-[11px] font-medium tracking-[0.12em] text-subtle uppercase">
              Aisle {g.aisle} · {g.items[0].product.department}
            </p>
          )}
          <ul className="divide-y divide-hairline">
            <AnimatePresence initial={false} mode="popLayout">
              {g.items.map((item) => (
                <Row key={item.product.id} item={item} onTogglePicked={onTogglePicked} inStore={inStore} />
              ))}
            </AnimatePresence>
          </ul>
        </div>
      ))}
    </div>
  );
}

